// ─── File: FailureLessonDemo.java ───
// Single runnable file with multiple top-level, package-private classes.

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Handler;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class FailureLessonDemo {

    private static final Logger log = Logger.getLogger(FailureLessonDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger rootLogger = Logger.getLogger("");
        for (Handler handler : rootLogger.getHandlers()) {
            rootLogger.removeHandler(handler);
        }
        ConsoleHandler consoleHandler = new ConsoleHandler();
        consoleHandler.setFormatter(new BankLogFormatter());
        consoleHandler.setLevel(Level.ALL);
        rootLogger.addHandler(consoleHandler);
        rootLogger.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info(() -> "Lesson from a real failure: auto-rollback at " + BANK_NAME);

        Version known = new Version("fee-service-1.0", true);
        DeploymentManager manager = new DeploymentManager(known, new HealthCheck());

        // A good deploy: fee calc fixed correctly, health check passes.
        manager.deploy(new Version("fee-service-1.1", true));

        // A bad deploy: the double-charge bug returns; health check fails, auto rollback.
        manager.deploy(new Version("fee-service-1.2-buggy", false));

        log.info(() -> "Currently serving: " + manager.current().getName());
    }
}

// ─── Would be in model/Version.java in a real project ───
class Version {
    private final String name;
    private final boolean healthy;

    Version(String name, boolean healthy) {
        this.name = name;
        this.healthy = healthy;
    }

    String getName() { return name; }
    boolean isHealthy() { return healthy; }
}

// ─── Would be in health/HealthCheck.java in a real project ───
// Runs right after deploy. In real life this would hit /health and verify fee math.
class HealthCheck {
    private static final Logger log = Logger.getLogger(HealthCheck.class.getName());

    boolean isHealthy(Version version) {
        log.fine(() -> "Running health check on " + version.getName());
        return version.isHealthy();
    }
}

// ─── Would be in deploy/DeploymentManager.java in a real project ───
// The safety mechanism my failure taught me to build.
class DeploymentManager {
    private static final Logger log = Logger.getLogger(DeploymentManager.class.getName());
    private Version current;
    private final HealthCheck healthCheck;

    DeploymentManager(Version initial, HealthCheck healthCheck) {
        this.current = initial;
        this.healthCheck = healthCheck;
    }

    void deploy(Version candidate) {
        Version previous = current;
        current = candidate;
        log.info(() -> "Deployed " + candidate.getName() + ", verifying health...");
        if (healthCheck.isHealthy(candidate)) {
            log.info(() -> candidate.getName() + " is healthy — keeping it live.");
        } else {
            log.severe(() -> candidate.getName() + " FAILED health check — rolling back to "
                    + previous.getName());
            current = previous;
            log.info(() -> "Auto-rolled back to " + previous.getName()
                    + ". Damage limited to seconds.");
        }
    }

    Version current() { return current; }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
                record.getMillis(),
                record.getLevel().getName(),
                record.getSourceClassName() != null
                        ? record.getSourceClassName().substring(
                                record.getSourceClassName().lastIndexOf('.') + 1)
                        : "Unknown",
                record.getMessage());
    }
}
